-- =====================================================
-- 竞赛管理重构 - 数据库增量脚本 v2
-- 在 Navicat 中打开所属数据库，逐条执行即可
-- =====================================================

-- 1. 给 competition 表添加 type 字段
ALTER TABLE `competition` ADD COLUMN `type` varchar(20) DEFAULT 'network' COMMENT '类型:network网络工程竞赛/general综合性竞赛';

-- 2. 将现有数据标记为网络工程竞赛
UPDATE `competition` SET `type` = 'network' WHERE `type` IS NULL;

-- 3. 插入综合性竞赛初始数据
INSERT INTO `competition` (`name`, `description`, `icon_img`, `bg_image`, `watermark`, `level`, `level_type`, `tag`, `time`, `organizer`, `techs`, `full_desc`, `mode`, `website`, `advice`, `suitable`, `grades`, `type`) VALUES
('中国大学生计算机设计大赛', '教育部高等学校计算机类专业教指委主办的全国性赛事，涵盖软件应用开发、数字媒体设计、人工智能应用等十余个类别，是国内规模最大、覆盖面最广的计算机类学科竞赛之一。', '@/assets/imgs/comp-jisuanji.png', 'linear-gradient(135deg, rgba(21, 101, 192, 0.9) 0%, rgba(41, 121, 255, 0.85) 100%)', 'JISUANJI', '国家级', 'national', '学科赛', '每年4月-8月', '教育部计算机类专业教指委', '软件开发,UI设计,人工智能,大数据', '中国大学生计算机设计大赛由教育部高等学校计算机类专业教学指导委员会主办，是国内规模最大、覆盖面最广的计算机类学科竞赛之一，每年参赛作品超过万件。大赛涵盖软件应用与开发、数字媒体设计、人工智能应用、物联网应用、大数据应用、信息可视化设计等十余个类别，参赛形式灵活，可个人或团队（1-5人）参赛。比赛分为校赛、省赛、国赛三级，作品需提交完整的设计文档、源代码和演示视频。该赛事注重创新性和实用性，获奖作品往往具有较高的市场转化潜力，在保研加分和求职作品集中都有很好的展示价值。', '个人/团队赛（1-5人）', 'jsjds.blcu.edu.cn/index.htm', '【选题策略】选择自己擅长且感兴趣的类别参赛，选题要有创新性和实用性，避免"大而全"的选题，建议聚焦一个具体痛点深入解决。软件类建议使用主流技术栈（Vue/React + Spring Boot/Node.js），设计类建议精通PS、AI、AE等工具。【作品要求】完整作品应包括：项目文档（需求分析、系统设计、技术架构）、源代码（GitHub仓库链接）、演示视频（3-5分钟，展示核心功能和使用场景）、海报展板。答辩时重点阐述创新点和核心算法，准备3-5分钟的PPT演讲。【时间规划】建议至少提前3个月开始准备，每月一个里程碑：第1月选题+需求分析，第2月开发+测试，第3月文档+视频+答辩准备。', '【报名方式】通过大赛官网（jsjds.ruc.edu.cn）在线报名，可个人或团队（1-5人）参赛。需先通过校赛选拔，校赛优胜者推荐参加省赛，省赛获奖者晋级国赛。【赛程安排】校赛（1-3月）→ 省赛（4-5月）→ 国赛（7-8月现场答辩）。【报名时间】每年1-3月关注学校教务处或计算机学院通知，部分学校会组织赛前培训和作品打磨。', '大一,大二,大三,大四', 'general'),

('全国大学生统计建模大赛', '中国统计教育学会主办的全国性学术竞赛，要求参赛者运用统计学方法和计算机技术对实际问题进行建模分析，涵盖数据挖掘、机器学习、经济预测等多个方向。', '@/assets/imgs/comp-tongjijianmo.png', 'linear-gradient(135deg, rgba(123, 31, 162, 0.88) 0%, rgba(156, 39, 176, 0.82) 100%)', 'TONGJI', '国家级', 'national', '学科赛', '每年3月-6月', '中国统计教育学会', '统计分析,机器学习,Python/R,数据可视化', '全国大学生统计建模大赛由中国统计教育学会主办，是统计学领域最具影响力的全国性学术竞赛。大赛要求参赛者运用统计学方法、机器学习算法和计算机技术，对经济、社会、环境等领域的实际问题进行建模分析，最终提交一篇规范的建模论文。比赛涵盖数据挖掘、机器学习、经济预测、生物统计、环境统计等多个方向，评委从选题价值、模型科学性、数据质量、分析深度和论文规范性五个维度进行评审。该赛事是统计学、数据科学、计算机等专业学生展示数据分析能力的绝佳平台，获奖论文有机会被推荐至统计学期刊发表。', '团队赛（3人）', 'tjjmds.ai-learning.net/', '【团队配置】建议组建跨专业团队：统计学专业负责模型设计和理论支撑、计算机专业负责编程实现和数据处理、经管/社科专业负责选题背景分析和论文撰写。这样的配置能让作品既有理论深度又有技术含量。【工具技能】重点掌握Python数据分析三件套（NumPy/Pandas/Matplotlib）+ 机器学习库（scikit-learn），或R语言（ggplot2/dplyr/tidyr）。数据可视化推荐使用Tableau或Power BI制作专业图表。【选题方向】建议选择社会热点或行业痛点问题：经济预测（GDP/CPI/房价）、公共卫生（疫情传播模型）、环境科学（空气质量预测）、交通出行（共享单车调度优化）等。关注历年优秀论文的选题思路和研究方法，学习规范的建模论文写作格式。【时间规划】赛题发布后建议48小时内完成选题和初步方案，72小时内完成数据收集和模型构建，最后2天集中撰写和修改论文。', '【报名方式】通过大赛官网（中国统计教育学会网站）在线报名，3人组队参赛。【赛程安排】赛题发布（3月）→ 团队选题和建模（3-4月，约1-2周完成）→ 提交建模论文（4月）→ 评审公布（5-6月）。【准备建议】赛前建议提前组队并磨合团队分工，准备好各自的工具环境和代码模板。关注大赛官网和中国统计教育学会公众号获取报名时间和赛题发布通知。', '大二,大三,大四', 'general'),

('全国大学生数学建模竞赛(CUMCM)', '教育部和中国工业与应用数学学会共同主办的全国规模最大的基础性学科竞赛，三人组队在三天内完成一个实际问题的数学建模、求解与论文撰写，被誉为国内含金量最高的学科竞赛之一。', '@/assets/imgs/comp-shuxuejianmo.png', 'linear-gradient(135deg, rgba(0, 121, 107, 0.9) 0%, rgba(38, 166, 154, 0.85) 100%)', 'CUMCM', '国家级', 'national', '学科赛', '每年9月', '中国工业与应用数学学会', '数学建模,MATLAB,算法设计,论文撰写', '全国大学生数学建模竞赛(CUMCM)由教育部高等教育司和中国工业与应用数学学会共同主办，是国内规模最大、参与人数最多、含金量最高的基础性学科竞赛，每年参赛队伍超过5万支。三人组队在三天三夜（72小时）内，从公布的A/B/C三道赛题中任选一题，完成从问题分析、模型建立、算法求解、结果分析到论文撰写的完整科研流程。赛题涵盖工程优化、经济预测、交通规划、环境评估、大数据分析等实际应用领域，全面考察学生的数学建模能力、编程求解能力、论文写作能力和团队协作能力。国赛一等奖在保研、考研复试和求职中都有极高的认可度。', '团队赛（3人，72小时封闭竞赛）', 'www.mcm.edu.cn/?key=TNBC%E7%AB%9E%E8%B5%9B%E5%AE%98%E7%BD%91', '【团队配置】经典3人分工：建模手（负责数学建模、公式推导、算法设计）、编程手（负责MATLAB/Python编程求解、数据可视化）、写作手（负责论文撰写、图表制作、格式排版）。三人需高度默契，赛前至少完成2-3次模拟真题训练。【技能储备】建模手：掌握微分方程、线性规划、图论模型、概率统计模型、评价模型（层次分析法/TOPSIS）等常用模型；编程手：熟练掌握MATLAB或Python（NumPy/SciPy/Matplotlib），能快速将模型转化为代码并调参优化；写作手：学术论文写作能力、LaTeX排版、Visio/PPT流程图制作。【赛前准备】推荐完成近5年国赛真题的模拟训练，练习时间控制在3天72小时内。建立自己的模型库和代码模板，比赛中直接调用改造。关注中国大学生数学建模竞赛官网和"数学建模"公众号获取赛前培训资源。', '【报名方式】通过学校统一报名，不接受个人报名。3人组队参赛，需先通过学校数学建模协会或数模指导老师组织的校内选拔赛。【赛程安排】赛题发布（每年9月第二个周四晚20:00）→ 三天三夜建模和论文撰写（周五、周六、周日）→ 提交论文（周一早8:00前）→ 赛区评审（10-11月）→ 全国评审（12月）。【报名时间】每年6-8月关注学校数模协会通知，部分学校在暑假组织赛前集训。建议大二下学期开始准备，大三上学期参赛。', '大二,大三,大四', 'general'),

('全国大学生软件创新大赛', '教育部软件工程专业教指委主办的全国性赛事，聚焦软件技术创新与应用，涵盖移动应用、云计算、人工智能软件、智能终端等多个方向，旨在培养创新型软件人才。', '@/assets/imgs/comp-ruanjianchuangxin.png', 'linear-gradient(135deg, rgba(74, 20, 140, 0.88) 0%, rgba(103, 58, 183, 0.82) 100%)', 'CHUANGXIN', '国家级', 'national', '学科赛', '每年4月-10月', '教育部软件工程教指委', '软件开发,架构设计,产品设计,AI应用', '全国大学生软件创新大赛由教育部软件工程专业教学指导委员会主办，聚焦软件技术创新与应用，是国内软件工程领域最具代表性的学科竞赛。大赛涵盖移动应用、云计算、人工智能软件、智能终端、大数据应用、区块链应用等多个技术方向，要求参赛团队提交一个完整的软件产品，包括产品策划书、技术方案、可运行的系统原型和路演答辩。评委从创新性（30%）、技术难度（25%）、用户体验（25%）、商业价值（20%）四个维度进行评审。获奖作品有机会获得投资机构关注和企业孵化支持，是展示软件工程综合能力的理想平台。', '团队赛（3-5人）', 'www.swcontest.com.cn/index', '【选题方向】选择有市场前景和商业价值的软件方向，作品要有完整的功能实现（非简单Demo），最好能展示真实用户场景。热门方向：AI+行业应用（智能教育/医疗/农业）、移动应用创新（小程序/App）、Web全栈开发、云原生应用等。【技术栈建议】前端：Vue3/React + TypeScript；后端：Spring Boot/Node.js/Go；数据库：MySQL + Redis；部署：Docker + Nginx。建议使用成熟的开发框架和组件库，关注代码质量和工程规范。【作品要求】Demo演示要流畅稳定，不要出现明显bug。准备清晰的产品介绍PPT（痛点分析→解决方案→技术架构→核心功能→市场前景），路演控制在5-8分钟。建议提前录制备用视频，防止现场演示出问题。', '【报名方式】通过大赛官网在线报名，3-5人组队参赛。建议团队包含产品经理（需求分析+商业计划）、前端开发、后端开发和UI设计四类角色。【赛程安排】初赛方案提交（4-5月，提交产品策划书+技术方案）→ 复赛开发实现（6-8月，完成MVP产品）→ 决赛路演答辩（9-10月，现场演示+评委问答）。【准备建议】建议在大二上学期开始构思产品方向，寒假完成技术选型和原型设计，下学期正式开发。', '大二,大三,大四', 'general'),

('蓝桥杯 · 软件类赛项', '蓝桥杯全国软件和信息技术专业人才大赛的软件类赛道，涵盖C/C++、Java、Python等编程语言组别，考察算法设计、数据结构与编程实现能力，是国内参与人数最多的IT学科竞赛之一。', '@/assets/imgs/comp-lanqiao.png', 'linear-gradient(135deg, rgba(74, 20, 140, 0.88) 0%, rgba(123, 31, 162, 0.82) 100%)', 'LANQIAO', '国家级', 'national', '学科赛', '每年10月-次年4月', '工信部人才交流中心', '数据结构,算法设计,C/C++,Java/Python', '蓝桥杯全国软件和信息技术专业人才大赛由工业和信息化部人才交流中心主办，是国内参与人数最多的IT学科竞赛，每年参赛人数超过10万人。软件类赛项涵盖C/C++、Java、Python等编程语言组别，考察算法设计与数据结构实现能力，省赛以填空题+编程题为主，国赛以编程题+算法设计题为主。比赛难度梯度合理，从基础语法到高级算法，适合从大一到大四各年级学生参与。获奖证书在求职和考研保研中都有较高认可度，多家知名企业（华为、腾讯、百度等）在招聘时认可蓝桥杯获奖成绩。', '个人赛', 'dasai.lanqiao.cn/', '【刷题为王】系统刷题是王道，强烈推荐使用蓝桥杯官方练习系统（dasai.lanqiao.cn）和LeetCode进行专项训练，建议完成300+题目的练习量。重点掌握以下高频考点：数据结构（数组、链表、栈、队列、树、图、哈希表）、基础算法（排序、二分查找、双指针、滑动窗口）、进阶算法（动态规划、贪心、DFS/BFS回溯、前缀和/差分）。【学习路径】第一阶段（入门）：完成C/C++或Java或Python语法学习，代码量达到5000行；第二阶段（基础）：在蓝桥杯练习系统完成200道基础题，目标是省赛获奖；第三阶段（冲刺）：在LeetCode刷100道Medium题目，备战国赛。【语言选择】C/C++是蓝桥杯最主流语言，STL库丰富；Java组别竞争相对较小；Python组别省赛简单但国赛难度大。建议选择学校课程对接的语言。', '【报名方式】通过蓝桥杯官网（dasai.lanqiao.cn）个人在线报名，可选择学校统一报名（享受优惠报名费约300元/人）。可同时报名多个语言组别。【赛程安排】报名（10月-次年3月）→ 省赛（4月，在各校/各省考点）→ 国赛（5-6月，北京等城市）。省赛和国赛均为线下机考，4小时完成8-10道编程题。【报名时间】报名通常在每年10月启动，截止至次年3月。建议尽早报名，早报名可享受更多练习系统使用时间。', '大一,大二,大三,大四', 'general'),

('ACM-ICPC 国际大学生程序设计竞赛', '全球历史最悠久、影响力最大的大学生程序设计竞赛，被称为计算机界的"奥林匹克"。赛题涉及图论、动态规划、网络流、计算几何等核心算法，对培养编程能力和算法思维有极大帮助。', '@/assets/imgs/comp-acm.png', 'linear-gradient(135deg, rgba(233, 30, 99, 0.9) 0%, rgba(255, 64, 129, 0.85) 100%)', 'ACM-ICPC', '国际级', 'international', '综合赛', '每年9月-次年4月', '国际计算机协会(ACM)', '算法设计,数据结构,图论,动态规划', 'ACM-ICPC（国际大学生程序设计竞赛）由国际计算机协会(ACM)主办，是全球历史最悠久、影响力最大、含金量最高的大学生程序设计竞赛，被称为计算机界的"奥林匹克"。比赛采用3人一队共用一台电脑，在5小时内完成8-12道算法题的形式，赛题涉及图论、动态规划、网络流、计算几何、数论、字符串、数据结构等核心算法领域。比赛不仅考验算法功底，更考验团队协作、时间管理和心理素质。ICPC获奖选手是各大科技公司（Google、Facebook、Microsoft、华为等）竞相争夺的人才，世界总决赛奖牌获得者往往能获得顶级offer。', '团队赛（3人，5小时）', 'icpc.global', '【训练体系】系统性算法训练四阶段：阶段一（基础）：掌握基础数据结构（数组、链表、栈、队列、树、图）和基础算法（排序、二分、DFS/BFS），在洛谷/Codeforces完成100道Div.2 A/B题；阶段二（进阶）：掌握动态规划、贪心、图论（Dijkstra/Floyd/Kruskal/Prim）、网络流（Edmonds-Karp/Dinic）、字符串（KMP），在Codeforces达到蓝名（1600+）；阶段三（高阶）：掌握线段树、树状数组、平衡树、数论、计算几何、竞赛图论，在Codeforces达到紫名（1900+）；阶段四（竞赛）：三人组队模拟训练，刷ICPC历年真题，重点是团队配合和读题速度。【团队配置】建议三人分工：一人负责数学+图论、一人负责数据结构+动态规划、一人负责字符串+计算几何。赛前每周至少进行1次3人合练，模拟5小时竞赛环境。【训练平台】Codeforces（每周比赛）、AtCoder（日本高质量竞赛）、Virtual Judge（ICPC真题合集）、洛谷（国内新手友好）。', '【报名方式】通过ICPC官网（icpc.global）或学校ACM集训队报名，3人组队参赛。国内可通过ICPC亚洲区域赛或CCPC（中国大学生程序设计竞赛）选拔进入世界总决赛。【参赛流程】校选赛（加入校队）→ 区域网络预选赛（9-10月）→ 亚洲区域赛（11-12月）→ 世界总决赛（次年4-6月）。【准备建议】建议大一加入学校ACM集训队，从新手开始系统训练。集训队通常有教练指导和老队员带新，是最高效的训练方式。关注学校ACM协会和CSDN ACM社区获取比赛信息。', '大一,大二,大三,大四', 'general'),

('全国大学生物联网设计竞赛', '教育部主办的物联网领域最高级别赛事，要求参赛者综合运用传感器网络、嵌入式系统、云计算、边缘计算等技术，完成从感知层到应用层的完整物联网系统设计。', '@/assets/imgs/comp-wulianwang.png', 'linear-gradient(135deg, rgba(1, 87, 155, 0.9) 0%, rgba(2, 136, 209, 0.85) 100%)', 'WULIANWANG', '国家级', 'national', '综合赛', '每年3月-8月', '教育部高等学校计算机类专业教指委', '传感器网络,嵌入式开发,云计算,边缘计算', '全国大学生物联网设计竞赛由教育部高等学校计算机类专业教学指导委员会主办，是国内物联网领域最高级别的学科竞赛，入选国家级A类竞赛榜单。大赛要求参赛者综合运用传感器网络、嵌入式系统、无线通信、云计算、边缘计算、大数据分析等技术，完成从感知层（传感器数据采集）到网络层（数据通信传输）到平台层（云端数据处理）到应用层（可视化展示+智能决策）的完整物联网系统设计。赛题涵盖智慧城市、智能家居、智慧农业、智慧医疗、工业物联网等应用场景，评委从创新性、技术难度、系统完整性和展示效果四个维度评审。获奖作品往往具有较高的产业化潜力，是物联网方向学生展示综合能力的最佳平台。', '团队赛（3-5人）', 'iotcompetition.org', '【团队配置】建议5人团队包含以下角色：嵌入式开发（硬件选型+传感器驱动+MCU编程）、通信协议（无线组网+数据传输）、云平台开发（设备接入+数据存储+API接口）、前端展示（Web/App数据可视化）、产品设计（需求分析+文档+答辩PPT）。【硬件平台】推荐组合：主控Arduino（入门）/ESP32（WiFi+蓝牙双模）/STM32（高性能）；传感器：温湿度DHT22、光敏、超声波、PM2.5；通信模块：WiFi（ESP8266/ESP32）、ZigBee（CC2530）、LoRa（SX1278）、蓝牙（HC-05）。【云平台】推荐使用OneNET（中国移动，免费额度大）、阿里云IoT、华为云IoT，三者都提供完善的设备SDK和数据可视化组件。【作品要求】必须完成从感知层（传感器采集）→ 网络层（数据传输）→ 平台层（云端处理）→ 应用层（可视化展示）的完整物联网系统。准备3-5分钟的演示视频，展示真实场景下的系统运行效果。', '【报名方式】通过大赛官网（iotcompetition.org）在线报名，3-5人组队参赛。【赛程安排】初赛方案评审（3-4月提交方案+原型视频）→ 复赛作品展示（5-7月提交完整作品）→ 决赛现场答辩（8月）。【准备建议】建议大一暑假开始学习Arduino/ESP32基础，大二上学期组队并确定选题方向，寒假完成硬件采购和原型搭建，下学期正式开发和优化。关注学校物联网实验室或创新实验室的资源支持。', '大二,大三,大四', 'general'),

('华为ICT大赛 · 基础软件赛道', '华为ICT大赛的基础软件赛道面向编程初学者开放，聚焦算法设计与编程基础能力，考察学生在数据结构、基础算法、编程语言（Python/C/C++/Java）等方面的掌握程度。相比其他高难度赛道，基础软件赛道难度梯度更友好，是大一新生接触华为认证体系的绝佳入口。', '@/assets/imgs/comp-huawai.png', 'linear-gradient(135deg, rgba(207, 10, 44, 0.9) 0%, rgba(220, 80, 60, 0.85) 100%)', 'HUAWEI', '国家级', 'national', '企业赛', '每年9月-次年5月', '华为技术有限公司', '数据结构,算法基础,Python,C/C++', '华为ICT大赛基础软件赛道是华为为编程初学者专门设立的入门级竞赛通道，入选中国高等教育学会"全国普通高校大学生竞赛排行榜"。赛道聚焦程序设计与算法基础，考察内容包括基本数据结构（数组、链表、栈、队列、树、图、哈希表）、经典算法（排序、查找、递归、贪心、分治、动态规划入门、回溯法）以及编程语言基础语法（Python推荐，C/C++也可）。比赛难度设置循序渐进，从基础编程语法题逐步过渡到简单算法设计题，非常适合大一、大二学生检验编程学习成果并积累竞赛经验。省赛获奖选手可同时获得华为认证考试优惠券，国赛获奖更有机会获得华为实习面试机会。', '个人赛', 'www.huawei.com/minisite/ict-competition-2024-2025-global/cn/index.html', '【入门路径】编程零基础建议从Python入手，语法简洁学习曲线平缓，一个月可掌握基础；有C语言基础的可直接刷题。推荐学习资源：Python官方教程 + 廖雪峰Python教程（基础语法）、LeetCode探索卡片（数据结构入门）、蓝桥杯练习系统（竞赛题型）。【刷题建议】每天坚持2-3道编程题，从简单题开始逐步提升难度。重点掌握：数组遍历、字符串处理、链表操作、哈希表计数、排序算法应用、简单递归、贪心思想。建议使用Python作为竞赛语言，代码简洁可读性强，竞赛中能节省大量时间。【备考策略】省赛前3个月开始系统备考：第1个月学习基础语法+简单算法题；第2个月刷蓝桥杯练习系统基础题；第3个月做模拟真题+查漏补缺。', '【报名方式】通过华为ICT学院官网（e.huawei.com/cn/talent/ict-academic）或学校华为ICT学院统一报名。【赛程安排】省赛（10-11月）→ 国赛（次年3-5月）。【报名时间】每年9月开学后密切关注学校华为ICT学院通知，通常由指导老师统一组织。', '大一,大二', 'general');

